CREATE FUNCTION public.validar_carteira_lancamento() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE w public.carteiras; BEGIN IF TG_OP='UPDATE' AND OLD.transferencia_id IS NOT NULL THEN RAISE EXCEPTION 'Transferência conciliada não pode ser editada isoladamente'; END IF; IF NEW.carteira_id IS NULL THEN SELECT id INTO NEW.carteira_id FROM public.carteiras WHERE grupo_id=NEW.grupo_id AND legado=NEW.conta; END IF; SELECT * INTO w FROM public.carteiras WHERE id=NEW.carteira_id AND grupo_id=NEW.grupo_id; IF w.id IS NULL THEN RAISE EXCEPTION 'Carteira não pertence ao grupo'; END IF; IF w.legado='gasolina' AND auth.uid() IS NOT NULL AND NOT public.module_access('moto') THEN RAISE EXCEPTION 'Sem acesso à Moto/Gasolina'; END IF; IF NEW.conta IS DISTINCT FROM (CASE WHEN w.legado IN ('alimentacao','refeicao') THEN w.legado ELSE 'dinheiro' END) THEN RAISE EXCEPTION 'Carteira e conta incompatíveis'; END IF; IF NEW.origem_modulo='feira' AND TG_OP='INSERT' AND (NOT w.na_feira OR w.moeda<>'BRL' OR w.legado='gasolina' OR EXISTS(SELECT 1 FROM public.metas WHERE carteira_id=w.id)) THEN RAISE EXCEPTION 'Carteira não disponível na Feira'; END IF; IF NEW.fonte='fixa' AND (NOT w.nas_fixas OR w.moeda<>'BRL' OR EXISTS(SELECT 1 FROM public.metas WHERE carteira_id=w.id)) THEN RAISE EXCEPTION 'Carteira aceita somente lançamentos manuais'; END IF; IF NEW.transferencia_id IS NOT NULL AND (w.tipo<>'financeiro' OR w.moeda<>'BRL' OR EXISTS(SELECT 1 FROM public.metas WHERE carteira_id=w.id) OR NEW.tipo NOT IN ('credito','debito') OR NOT NEW.pago OR NEW.destino<>'geral' OR NEW.origem_modulo<>'financas') THEN RAISE EXCEPTION 'Carteira não elegível para transferência'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_entry_wallet BEFORE INSERT OR UPDATE ON public.lancamentos FOR EACH ROW EXECUTE FUNCTION public.validar_carteira_lancamento();
CREATE FUNCTION public.conciliar_transferencia() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE tid uuid; n integer; BEGIN tid:=COALESCE(NEW.transferencia_id,OLD.transferencia_id); IF tid IS NULL THEN RETURN NULL; END IF; SELECT count(*) INTO n FROM public.lancamentos WHERE transferencia_id=tid; IF n=0 THEN RETURN NULL; END IF; IF n<>2 OR (SELECT count(DISTINCT tipo) FROM public.lancamentos WHERE transferencia_id=tid)<>2 OR (SELECT count(DISTINCT carteira_id) FROM public.lancamentos WHERE transferencia_id=tid)<>2 OR (SELECT count(DISTINCT grupo_id) FROM public.lancamentos WHERE transferencia_id=tid)<>1 OR (SELECT count(DISTINCT valor) FROM public.lancamentos WHERE transferencia_id=tid)<>1 OR (SELECT count(DISTINCT data) FROM public.lancamentos WHERE transferencia_id=tid)<>1 THEN RAISE EXCEPTION 'Transferência exige débito e crédito conciliados'; END IF; RETURN NULL; END $$;
CREATE CONSTRAINT TRIGGER reconcile_transfer AFTER INSERT OR UPDATE OR DELETE ON public.lancamentos DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.conciliar_transferencia();
CREATE FUNCTION public.validar_fixa_carteira() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE w public.carteiras; BEGIN IF NEW.carteira_id IS NULL THEN SELECT id INTO NEW.carteira_id FROM public.carteiras WHERE grupo_id=NEW.grupo_id AND legado=(CASE WHEN NEW.modalidade='gasolina' THEN 'gasolina' ELSE NEW.conta END); END IF; SELECT * INTO w FROM public.carteiras WHERE id=NEW.carteira_id AND grupo_id=NEW.grupo_id; IF w.id IS NULL OR NOT w.nas_fixas OR w.moeda<>'BRL' OR EXISTS(SELECT 1 FROM public.metas WHERE carteira_id=w.id) THEN RAISE EXCEPTION 'Carteira não disponível para contas fixas'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_recurring_wallet BEFORE INSERT OR UPDATE ON public.contas_fixas FOR EACH ROW EXECUTE FUNCTION public.validar_fixa_carteira();
DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.gerar_contas_fixas(uuid)'::regprocedure) INTO definition; definition:=replace(definition,'origem_modulo,criado_por)','origem_modulo,criado_por,carteira_id,fonte)'); definition:=replace(definition,'''financas'',f.criado_por);','''financas'',f.criado_por,CASE WHEN f.modalidade=''gasolina'' THEN NULL ELSE f.carteira_id END,''fixa'');'); definition:=replace(definition,'ORDER BY c.id FOR UPDATE LOOP','AND (c.carteira_id IS NULL OR EXISTS(SELECT 1 FROM public.carteiras w WHERE w.id=c.carteira_id AND w.nas_fixas AND w.moeda=''BRL'' AND NOT EXISTS(SELECT 1 FROM public.metas m WHERE m.carteira_id=w.id))) ORDER BY c.id FOR UPDATE LOOP'); EXECUTE definition; END $$;
DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.sync_offline_operation(uuid,uuid,jsonb)'::regprocedure) INTO definition; definition:=replace(definition,'''despesas'',''contas_fixas'')','''despesas'',''contas_fixas'',''carteiras'',''metas'')'); definition:=replace(definition,'''destino'',''origem_modulo'']','''destino'',''origem_modulo'',''carteira_id'',''transferencia_id'',''categoria'',''fonte'']'); definition:=replace(definition,'''data_compra'',''local'']','''data_compra'',''local'',''carteira_id'']'); definition:=replace(definition,'''fim'',''ativa'']','''fim'',''ativa'',''carteira_id'']'); definition:=replace(definition,'WHEN ''contas_fixas'' THEN','WHEN ''carteiras'' THEN ARRAY[''nome'',''tipo'',''moeda'',''cor'',''icone'',''na_feira'',''nas_fixas'',''no_painel''] WHEN ''metas'' THEN ARRAY[''nome'',''carteira_id'',''valor_alvo'',''data_limite'',''ativa''] WHEN ''contas_fixas'' THEN'); EXECUTE definition; END $$;
REVOKE ALL ON FUNCTION public.validar_carteira_lancamento(),public.conciliar_transferencia(),public.validar_fixa_carteira() FROM PUBLIC;